class Account:
    def __init__(self, account_id, owner, balance, account_type):
        self.account_id = account_id
        self.owner = owner
        self.balance = balance
        self.account_type = account_type

    def deposit(self, amount):
        self.balance += amount
        print(f"Deposited {amount} into account {self.account_id}.")

    def withdraw(self, amount):
        if amount > self.balance:
            print(f"Insufficient funds in account {self.account_id}.")
        else:
            self.balance -= amount
            print(f"Withdrew {amount} from account {self.account_id}.")

    def get_balance(self):
        return self.balance


class Bank:
    def __init__(self):
        self.accounts = {}

    def create_account(self, account_id, owner, balance, account_type):
        if account_id in self.accounts:
            print(f"Account {account_id} already exists.")
        else:
            self.accounts[account_id] = Account(account_id, owner, balance, account_type)
            print(f"Account {account_id} created successfully.")

    def get_account(self, account_id):
        if account_id in self.accounts:
            return self.accounts[account_id]
        else:
            print(f"Account {account_id} not found.")
            return None

    def list_accounts(self):
        for account_id, account in self.accounts.items():
            print(f"Account ID: {account_id}, Owner: {account.owner}, Balance: {account.get_balance()}, Type: {account.account_type}")


def main():
    bank = Bank()

    while True:
        print("\n1. Create Account")
        print("2. List Accounts")
        print("3. Withdraw")
        print("4. Deposit")
        print("5. Exit")
